  'Ik ga akkoord met de EUPL 1.2-licentie en heb gelezen welke gegevens OciDeck bewaart.':
      'Akceptuję licencję EUPL 1.2 i zapoznałem się z tym, jakie dane przechowuje OciDeck.',
  'Lees de volledige licentie': 'Przeczytaj pełną licencję',
  'OciDeck is vrije software onder de EUPL 1.2-licentie. Voordat je begint, vragen we je de licentie te accepteren. Hieronder lees je ook welke gegevens OciDeck op dit apparaat bewaart en wanneer er iets je apparaat verlaat.':
      'OciDeck to wolne oprogramowanie na licencji EUPL 1.2. Zanim zaczniesz, prosimy o zaakceptowanie licencji. Poniżej możesz również przeczytać, jakie dane OciDeck przechowuje na tym urządzeniu i kiedy cokolwiek opuszcza Twoje urządzenie.',
  'OciDeck verzamelt geen statistieken en stuurt uit zichzelf niets naar buiten. Standaard blijft alles op dit apparaat. Gegevens verlaten dit apparaat alleen als jij dat kiest:\n\n•  Nextcloud/WebDAV: verbind je met een server, dan worden je inlognaam en wachtwoord bewaard (het wachtwoord veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die server verstuurd.\n•  Openen via URL: OciDeck haalt het bestand op van het adres dat je invoert.\n•  Online media (staat standaard uit): indien ingeschakeld laadt OciDeck afbeeldingen en video\'s van de adressen in je dia\'s.\n•  Externe links (zoals de online licentie) openen in je browser.':
      'OciDeck nie zbiera żadnych statystyk i sam z siebie nic nie wysyła na zewnątrz. Domyślnie wszystko pozostaje na tym urządzeniu. Dane opuszczają to urządzenie tylko wtedy, gdy sam to wybierzesz:\n\n•  Nextcloud/WebDAV: gdy łączysz się z serwerem, Twoja nazwa użytkownika i hasło są przechowywane (hasło bezpiecznie w pęku kluczy systemu), a prezentacje, które otwierasz lub zapisujesz, są wysyłane na ten serwer.\n•  Otwieranie przez URL: OciDeck pobiera plik z podanego przez Ciebie adresu.\n•  Media online (domyślnie wyłączone): po włączeniu OciDeck ładuje obrazy i filmy z adresów w Twoich slajdach.\n•  Linki zewnętrzne (takie jak licencja online) otwierają się w Twojej przeglądarce.',
  'OciDeck wordt geleverd onder de European Union Public Licence v1.2. Door akkoord te gaan aanvaard je deze licentie. Je mag OciDeck gebruiken, kopiëren, aanpassen en verspreiden onder de voorwaarden van de EUPL 1.2.':
      'OciDeck jest udostępniany na licencji European Union Public Licence v1.2. Wyrażając zgodę, akceptujesz tę licencję. Możesz używać, kopiować, modyfikować i rozpowszechniać OciDeck na warunkach EUPL 1.2.',
  'Om te werken en je werk niet te verliezen, bewaart OciDeck gegevens lokaal op dit apparaat:\n\n•  Je instellingen en voorkeuren (taal, mappen, stijl- en weergaveprofielen, recente bestanden).\n•  Je presentatiematerialen: de presentaties die je opslaat, automatische herstelkopieën en bijlagen zoals afbeeldingsbeschrijvingen.\n•  Deze toestemmingskeuze.\n\nJe kunt dit verwijderen door de bestanden te wissen of de instellingen te resetten.':
      'Aby działać i chronić Twoją pracę, OciDeck przechowuje dane lokalnie na tym urządzeniu:\n\n•  Twoje ustawienia i preferencje (język, foldery, profile stylu i wyglądu, ostatnie pliki).\n•  Twoje materiały prezentacyjne: zapisywane prezentacje, automatyczne kopie odzyskiwania oraz załączniki, takie jak opisy obrazów.\n•  Ten wybór zgody.\n\nMożesz to usunąć, kasując pliki lub resetując ustawienia.',
