  'Thema, slides, footer, checklist en titels over afbeeldingen, getoetst aan WCAG AA (4,5:1 voor tekst, 3:1 voor grote tekst).':
      'Motyw, slajdy, stopka, lista kontrolna i tytuły na obrazach, sprawdzone względem WCAG AA (4,5:1 dla tekstu, 3:1 dla dużego tekstu).',
  'Elke afbeelding, grafiek, video en audio heeft een beschrijving nodig voor schermlezers en bijsluiters.':
      'Każdy obraz, wykres, film i dźwięk potrzebuje opisu dla czytników ekranu i materiałów drukowanych.',
  'Verwijzingen naar afbeeldingen, video en audio worden gecontroleerd op een bestaand bestand in het project.':
      'Odwołania do obrazów, filmów i dźwięku są sprawdzane pod kątem istnienia pliku w projekcie.',
  'Aantal en lengte van bullets, woorden, nesting, kolombalans en de dichtheid van quotes, titels, tabellen en code zodat alles leesbaar past.':
      'Liczba i długość punktorów, słów, zagnieżdżenie, równowaga kolumn oraz gęstość cytatów, tytułów, tabel i kodu, tak aby wszystko czytelnie się mieściło.',
  'Bodytekst met contrast onder {crit}:1 telt als fout; daarboven tot de AA-norm als waarschuwing.':
      'Tekst podstawowy o kontraście poniżej {crit}:1 liczy się jako błąd; powyżej tej wartości aż do normy AA jako ostrzeżenie.',
  'Geen drempelwaarde: een niet-lege beschrijving is verplicht.':
      'Bez wartości progowej: niepusty opis jest wymagany.',
  'Geen drempelwaarde: het gekoppelde bestand moet binnen de projectmap bestaan.':
      'Bez wartości progowej: powiązany plik musi istnieć w folderze projektu.',
  'Waarschuwing boven {b1} bullets (1 kolom), {bcl} (checklist) of {b2} (2 kolommen); kritiek boven {bc1} of {bc2}. Woorden boven {w1}/{w2}, gemiddeld boven {avg} per bullet. Quote boven {q} tekens, titel boven {t} tekens. Nesting dieper dan niveau {lvl}. Tekst die tot onder {warn}% moet krimpen waarschuwt, onder {crit}% is kritiek.':
      'Ostrzeżenie powyżej {b1} punktorów (1 kolumna), {bcl} (lista kontrolna) lub {b2} (2 kolumny); krytyczne powyżej {bc1} lub {bc2}. Słowa powyżej {w1}/{w2}, średnio powyżej {avg} na punktor. Cytat powyżej {q} znaków, tytuł powyżej {t} znaków. Zagnieżdżenie głębsze niż poziom {lvl}. Tekst, który musi zmniejszyć się poniżej {warn}%, generuje ostrzeżenie, poniżej {crit}% jest krytyczny.',
