      'Rozdzielone przecinkami, np. OWASP WSTG@4.2',
  'Titel van de presentatie': 'Tytuł prezentacji',
  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · Wstrzyknięcie SQL w formularzu logowania',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?': 'Wysłać ten obraz do modelu AI?',
  'De afbeelding gaat ongewijzigd naar': 'Obraz zostanie wysłany bez zmian do',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck niczego nie redaguje w obrazie: twarze, tekst na zrzucie ekranu i widoczne dane zostaną wysłane.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Kontrola obrazu wykryła tu jedną lub więcej rozpoznawalnych twarzy.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Obok eksportu powstają dwa pliki, dzięki którym odbiorca może sprawdzić redakcje.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'wymienia, co zostało pominięte, bez samych wartości. Ten plik może trafić razem z raportem.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'zawiera klucze pozwalające odtworzyć każdą zredagowaną wartość. Nie wysyłaj tego pliku: redakcja zostanie wtedy cofnięta. Przechowuj go przy źródle.',
  'slides': 'slajdy',
  'Achtergehouden': 'Wstrzymany',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Wstrzymany: sklasyfikowany surowiej niż prezentacja',
  '1 slide achtergehouden door haar TLP': '1 slajd wstrzymany przez swój TLP',
  'slides achtergehouden door hun TLP': 'slajdy wstrzymane przez ich TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Te slajdy nie trafiają do prezentacji, eksportu ani pakietu. Podnieś poziom TLP prezentacji w Informacjach o prezentacji, aby je uwzględnić.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Wszystkie slajdy są wstrzymane przez ich klasyfikację TLP, więc nie ma nic do pokazania.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Wszystkie slajdy są wstrzymane przez ich klasyfikację TLP, więc nie ma nic do wyeksportowania.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Wszystkie slajdy są pominięte lub wstrzymane przez ich klasyfikację TLP, więc nie ma nic do pokazania.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Wszystkie slajdy są pominięte lub wstrzymane przez ich klasyfikację TLP, więc nie ma nic do wyeksportowania.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Dane liczbowe wykresów nie zostały zapisane — istnieją już tylko w tym oknie:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'W przeglądarce nie ma odzyskiwania po awarii: jeśli zamkniesz tę kartę, niezapisana praca przepadnie. Zapisz prezentację samodzielnie.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Lokalna baza CVE (pobieranie uruchamiasz sam): OciDeck pobiera dane zbiorcze przez api.github.com oraz plik wydania, na który ten adres wskazuje.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Wyszukiwanie CVE (domyślnie wyłączone): gdy jest włączone, wyszukiwana fraza trafia do skonfigurowanego serwera lustrzanego CVE, a jeśli ten nic nie znajdzie — do europejskiej bazy ENISA i do MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Osadzony film z YouTube lub Vimeo ładuje odtwarzacz z tej usługi.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  W przeglądarce: jeśli przeglądarka odmówi bezpośredniego pobrania adresu, OciDeck próbuje ponownie przez serwer, z którego pochodzi aplikacja; ten adres trafia wtedy do tego serwera.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Cofnięcie zgody nie zostało zapisane. Przy następnym uruchomieniu zgoda znów będzie obowiązywać.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Nagłówek sekcji zapowiadający nową część prezentacji. Zwięźle. Dodaj obraz tła z biblioteki obrazów.',
  'Bronnen doorzoeken…': 'Przeszukiwanie źródeł…',
  'Niet doorzocht': 'Nie przeszukano',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Ta kontrola nie działa w wersji internetowej: wykrywanie twarzy wymaga biblioteki systemowej, której przeglądarka nie ma. Użyj wersji desktopowej, aby sprawdzić twarze na obrazach.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Token musi mieć dostęp do odczytu i zapisu repozytorium. Gitea i Forgejo nie mają wyszukiwania po stronie serwera; OciDeck szuka lokalnie.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Token musi mieć zakres repo (lub szczegółowo: Contents do odczytu i zapisu).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Token musi mieć read_repository, write_repository i read_api. Wyszukiwanie po stronie serwera wymaga Advanced lub Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Szybkie wyszukiwanie po stronie serwera — z powodu opóźnienia indeksowania niedawno zmieniona talia może się nie pojawić.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Multimedia nie są zachowywane w zwykłym pliku .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Obrazy, wideo i dźwięk wybrane na tej karcie istnieją tylko w pamięci. Zwykły plik .md ich nie zachowa — znikną po ponownym otwarciu. Wyeksportuj jako pakiet .ocideck, aby zabrać multimedia ze sobą.',
  'Media verwijderd om privacyredenen':
      'Multimedia usunięte ze względów prywatności',
