  'Vingerafdruk (SHA-256)': 'Odcisk (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Zaufanie dotyczy tylko tego jednego certyfikatu. Jeśli serwer go później wymieni, OciDeck zapyta ponownie.',
  'Vertrouwen': 'Zaufaj',
  'Certificaat bekijken': 'Pokaż certyfikat',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Miejsca, w których przechowujesz i przeszukujesz swoje prezentacje — foldery na tym komputerze, serwery WebDAV, zasobniki S3 i repozytoria git razem. Przeciągnij je w kolejności, jaką chcesz: najwyższy danego rodzaju liczy się jako domyślny.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Magazyn S3: gdy łączysz się z zasobnikiem, zapisywane są punkt końcowy, nazwa zasobnika i twój klucz dostępu (tajny klucz bezpiecznie w pęku kluczy twojego systemu), a prezentacje, które otwierasz lub zapisujesz, są wysyłane do tej usługi magazynowania.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Magazyn Git: gdy łączysz się z repozytorium, zapisywany jest twój token dostępu (bezpiecznie w pęku kluczy twojego systemu), a prezentacje, które zapisujesz, są wysyłane na ten serwer jako commity. Kopia robocza repozytorium pozostaje niezaszyfrowana na tym urządzeniu.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Dla języka tej prezentacji brakuje nazw chorób. Religia, poglądy polityczne i terminy związkowe są rozpoznawane, a wzorce z cyfrą kontrolną (PESEL, IBAN, paszport) działają zawsze — ale nie licz na wykrycie diagnozy.',
  'niet getest': 'nieprzetestowane',
  'Werkte op': 'Działało dnia',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Jesteś zalogowany, ale nie masz tu dostępu. Hasło nie jest problemem — poproś administratora o prawa do tego folderu.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Twój token jest ważny, ale nie ma na to uprawnień. Nadaj mu więcej praw albo poczekaj, jeśli forge stosuje limit.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Token jest ważny, ale nie ma na to uprawnień — nadaj mu więcej praw do repozytorium.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Zalogowano, ale brak dostępu — hasło nie jest problemem. Poproś o prawa do tego folderu.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'To wygląda na pełny adres URL DAV. Przy Nextcloud OciDeck sam wyprowadza tę ścieżkę — tutaj należy podać tylko serwer.',
  'Overnemen': 'Zastosuj',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV nie jest (dobrze) skonfigurowany — sprawdź dane serwera w Ustawienia → Magazyn.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Repozytorium git nie jest (dobrze) skonfigurowane — sprawdź serwer, właściciela i repozytorium w Ustawienia → Magazyn.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Nazwa serwera forge nie istnieje lub nie można jej odnaleźć. Sprawdź, czy w adresie URL serwera nie ma literówki.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Ten forge ma adres prywatny lub LAN. Oznacz go jako zaufany wewnętrzny w Ustawienia → Magazyn.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge jest nieosiągalny — sprawdź połączenie i adres URL serwera.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Logowanie do forge nie powiodło się. Sprawdź token: potrzebuje dostępu do odczytu repozytorium i do zapisu, aby zapisywać.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Nie znaleziono w repozytorium — albo twój token nie może tego zobaczyć.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge zwrócił błąd. Spróbuj ponownie później.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Ten adres nie odpowiada jak forge. Czy rodzaj forge w Ustawienia → Magazyn jest właściwy?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Najpierw skonfiguruj serwer WebDAV w Ustawienia → Magazyn.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Potrzebne, gdy forge działa w sieci prywatnej lub domowej. Bez tej opcji kontrola bezpieczeństwa odrzuca adres prywatny.',
  'Vul server-URL, eigenaar en repository in':
      'Wypełnij adres URL serwera, właściciela i repozytorium',
  'de standaardbranch heet': 'gałąź domyślna nazywa się',
  'die wordt voortaan gebruikt': 'od teraz będzie używana ta',
  'de repository is nog leeg; de eerste opslag vult hem':
      'repozytorium jest jeszcze puste; pierwszy zapis je wypełni',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'uwaga: ten token może tylko czytać, więc zapis się nie powiedzie',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Logowanie nie powiodło się — sprawdź token. Potrzebuje dostępu do odczytu repozytorium oraz do zapisu, aby móc zapisywać.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Nie znaleziono repozytorium — albo twój token nie może go zobaczyć. Sprawdź właściciela i nazwę repozytorium.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Ten adres nie odpowiada jak forge. Czy wybrany rodzaj forge jest właściwy?',
  'kenteken': 'numer rejestracyjny',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Dla języka tej prezentacji nie ma listy słów kluczowych dla szczególnych kategorii danych osobowych. Wzorce z cyfrą kontrolną (PESEL, IBAN, paszport) działają; słowa takie jak „diagnoza” czy „podejrzany” nie są rozpoznawane.',
  'Landpakketten voor identificatienummers':
      'Pakiety krajowe dla numerów identyfikacyjnych',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Numery takie jak holenderski BSN czy polski PESEL są przypisane do kraju. Cała Europa jest włączona, bo większość tych numerów ma cyfrę kontrolną: ich włączenie prawie nie kosztuje fałszywych alarmów. IBAN, e-mail, sekrety i paski paszportowe są od tego niezależne i zawsze są sprawdzane.',
  'strafrechtelijk gegeven (verdachte)': 'dane karne (podejrzany)',
