  'Geaccepteerd': 'Zaakceptowane',
  'Gewaarschuwd': 'Z ostrzeżeniem',
  'Weggelaten': 'Pominięte',
  'Bewerkbaar': 'Edytowalne',
  'De privacycontrole': 'Kontrola prywatności',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'OciDeck przegląda Twoje slajdy pod kątem danych, które mogą być wrażliwe: numery identyfikacyjne, dane kontaktowe, numery telefonów, rachunki bankowe, klucze i hasła oraz szczególne kategorie danych osobowych. Wszystko dzieje się na tym urządzeniu: nic nie jest wysyłane, a znaleziona wartość nie pojawia się w żadnym komunikacie.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Kontrola nie gwarantuje, że wszystko zostanie znalezione; zmniejsza ryzyko niezamierzonego wycieku danych osobowych.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Tekst na obrazach pozostaje niewidoczny, pliki z odnośników nie są otwierane, a danych bez rozpoznawalnego wzorca nie rozpozna żaden skaner. Slajd bez ostrzeżeń to slajd, na którym *my* niczego nie znaleźliśmy — a nie slajd, o którym wiadomo, że nic na nim nie ma. To, co udostępniasz, pozostaje Twoją decyzją i Twoją odpowiedzialnością.',
  'telefoonnummer': 'numer telefonu',
  'Voor wie is deze export?': 'Dla kogo jest ten eksport?',
  'Volledig': 'Pełny',
  'Geredigeerd': 'Zredagowany',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Dla zleceniodawcy lub audytora: usuwane jest tylko to, co oznaczyłeś jako "pomiń". Reszta pozostaje czytelna, aby strona trzecia mogła zweryfikować ustalenia.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Dla szerszego grona: usuwane jest wszystko, co znajdzie kontrola, także na zaakceptowanych slajdach. Plik dostaje "-geredigeerd" w nazwie.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'tabela danych osobowych (wiersze×kolumny)',
  'massa-persoonsgegevens op één slide':
      'masowe dane osobowe na jednym slajdzie',
  'gebruikerspad met een naam erin': 'ścieżka użytkownika zawierająca imię',
  'toegangstoken in een link': 'token dostępu w linku',
  'persoonsgegeven in een link': 'dana osobowa w linku',
  'deellink met ingebakken toegang': 'link udostępniania z wbudowanym dostępem',
  'e-mailadres in een link': 'adres e-mail w linku',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'osadzony obraz — nie możemy do niego zajrzeć',
  'Je eigen gegevens': 'Twoje własne dane',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Po jednym w wierszu: twoje imię, adres e-mail, numer telefonu lub domena twojej organizacji. To, co tu wpiszesz, nie jest zgłaszane ani redagowane — to nadawca, nie ustalenie. Domena (example.org) obejmuje każdy adres pod nią.',
  'Bij onafgehandelde persoonsgegevens':
      'Przy nierozstrzygniętych danych osobowych',
  'Export afgebroken vanwege privacybevindingen.':
      'Eksport przerwany z powodu ustaleń dotyczących prywatności.',
  'Export blokkeren': 'Zablokuj eksport',
  'Export geblokkeerd': 'Eksport zablokowany',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Eksport zablokowany: w tej prezentacji są dane osobowe, o których jeszcze nie zdecydowano.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
      'Wybierz dla każdego slajdu, co ma się stać, albo świadomie wyeksportuj tak, jak jest.',
  'Maak per slide een keuze (accepteren, waarschuwen of weglaten) voordat je exporteert. Dit is zo ingesteld bij Beveiliging.':
      'Wybierz dla każdego slajdu (akceptuj, ostrzegaj lub pomiń) przed eksportem. Tak ustawiono w Bezpieczeństwie.',
